SHORTCUTS = {
 "shop_customer": "shop/customer",
 "shop_material": "shop/material",
 "shop_payment": "shop/payment",
 "shop_review": "shop/review",
 "shop_sales_order_header": "shop/sales_order_header",
 "shop_sales_order_item": "shop/sales_order_item",
 "shop_vendor": "shop/vendor",
 "wb_delivery_flag": "wb/delivery_flag",
 "wb_forecast_override": "wb/forecast_override",
 "wb_reorder_policy": "wb/reorder_policy"
}

import time

SQLDB_ID = item_id("sqldb_shop", "SQLDatabase")
BRONZE_ID = item_id("lh_bronze", "Lakehouse")
existing = {s["name"] for s in fabric("GET", f"workspaces/{WS_ID}/items/{BRONZE_ID}/shortcuts").get("value", [])}
for name, target in SHORTCUTS.items():
    if name in existing:
        continue
    body = {"path": "Tables/dbo", "name": name,
            "target": {"oneLake": {"workspaceId": WS_ID, "itemId": SQLDB_ID, "path": f"Tables/{target}"}}}
    for attempt in range(10):  # the mirror may still be replicating a new table
        try:
            fabric("POST", f"workspaces/{WS_ID}/items/{BRONZE_ID}/shortcuts", body)
            changes.append(f"shortcut bronze.{name} -> sqldb_shop/{target}")
            break
        except RuntimeError as e:
            if attempt == 9:
                raise
            print(f"waiting for mirror of {target}: {e}")
            time.sleep(30)

